def close(self) -> None:
    """Terminate the shell and release the PTY.

    Idempotent: calling ``close`` more than once (for example an explicit
    call followed by ``__del__``) will not touch the master fd a second
    time, which is important because the fd number can be reused by another
    :class:`HeadlessTerminal` created after this one was closed.
    """
    if self._closed:
        return
    self._closed = True
    self._alive = False
    try:
        os.kill(self._pid, signal.SIGKILL)
    except (ProcessLookupError, OSError):
        pass
    try:
        os.waitpid(self._pid, 0)
    except (ChildProcessError, OSError):
        pass
    try:
        os.close(self._master_fd)
    except OSError:
        pass
    self._master_fd = -1
